window.BABA.Narration = {"intro":{"text":"Bu tapınakta ölüm bir son değil. Celladın zinciri kırılmadan kimse mezarında kalamıyor.","speaker":"Anlatıcı","duration":6.715,"audio":""},"chains":{"text":"Bu nöbetçiler celladın ilk kurbanlarıydı. Boyunlarındaki zincir, onları hâlâ onun emrine bağlıyor.","speaker":"Anlatıcı","duration":7.782,"audio":""},"ritual":{"text":"Yaralıları buraya iyileştirmek için getirdiler. Rahipler, acılarını ayini beslemek için kullandı.","speaker":"Anlatıcı","duration":7.343,"audio":""},"crypt":{"text":"Sunağa dökülen kan, cellada güç veriyor. Bu ayin bitmeden tapınak susmayacak.","speaker":"Anlatıcı","duration":6.658,"audio":""},"rot":{"text":"Bu kemikler mezarlarından söküldü. Geçidin taşına harç, celladın zincirine mühür oldular.","speaker":"Anlatıcı","duration":7.077,"audio":""},"checkpoint":{"text":"Yemin taşı seni hatırlayacak. Canını tazele. Sonraki kapının ardında cellat var.","speaker":"Anlatıcı","duration":7.724,"audio":""},"boss":{"text":"Bu hüküm cellatla yaşıyor. Zincirini kır.","speaker":"Anlatıcı","duration":4.013,"audio":""},"heroOath":{"text":"Onları burada bırakmayacağım.","speaker":"Bahtiyar","duration":1.705,"audio":""},"cellat":{"text":"Bu kapıdan kimse geçemez.","speaker":"Zincir Celladı","duration":1.774,"audio":""},"seal":{"text":"Zincirin bir halkası daha koptu. İlerle.","speaker":"Anlatıcı","duration":3.996,"audio":""},"death":{"text":"Yemin henüz bozulmadı. Taş seni geri çağırıyor.","speaker":"Anlatıcı","duration":4.262,"audio":""},"death2":{"text":"Bu mezar seni tutamayacak. Ayağa kalk.","speaker":"Anlatıcı","duration":3.87,"audio":""},"death3":{"text":"Bir kez daha düştün. Ama yemin duruyor; zincir hâlâ kırılabilir.","speaker":"Anlatıcı","duration":5.626,"audio":""},"win":{"text":"Cellat öldü; hükmü sona erdi. Tapınağın ölüleri artık yatabilir. Ama aşağıdan gelen o nefes, hâlâ kesilmedi.","speaker":"Anlatıcı","duration":10.206,"audio":""}};
